import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';

export const READING = 'reading';
export const FINISHED = 'finished';

const LIMITS = { title: 300, author: 300, notes: 20000 };

/**
 * A book library backed by a single JSON file.
 *
 * Every operation reads the file fresh and writes it back through a serialised
 * queue, so two overlapping requests can never clobber each other's changes.
 */
export function createStore(file) {
  const absFile = path.resolve(file);
  let tail = Promise.resolve();

  // Run fn with exclusive access to the file, one caller at a time.
  function exclusive(fn) {
    const result = tail.then(fn, fn);
    tail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async function read() {
    let raw;
    try {
      raw = await readFile(absFile, 'utf8');
    } catch (err) {
      if (err.code === 'ENOENT') return [];
      throw err;
    }
    if (raw.trim() === '') return [];

    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      throw new Error(`${absFile} does not contain a JSON array of books`);
    }
    return parsed;
  }

  async function write(books) {
    await mkdir(path.dirname(absFile), { recursive: true });
    // Write beside the target then rename, so a crash mid-write cannot leave a
    // truncated library behind.
    const tmp = `${absFile}.${process.pid}.tmp`;
    await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(tmp, absFile);
  }

  async function update(fn) {
    const books = await read();
    const outcome = fn(books);
    await write(books);
    return outcome;
  }

  return {
    file: absFile,

    /** All books, newest addition first. */
    all() {
      return exclusive(async () => {
        const books = await read();
        return books.slice().reverse();
      });
    },

    get(id) {
      return exclusive(async () => {
        const books = await read();
        return books.find((book) => book.id === id) ?? null;
      });
    },

    /** @returns the created book. Throws if the title is missing. */
    add({ title, author = '', notes = '' } = {}) {
      const book = {
        id: randomUUID(),
        title: clean(title, LIMITS.title),
        author: clean(author, LIMITS.author),
        notes: clean(notes, LIMITS.notes),
        status: READING,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      if (book.title === '') throw new ValidationError('A title is required.');

      return exclusive(() =>
        update((books) => {
          books.push(book);
          return book;
        }),
      );
    },

    /** @returns the updated book, or null if no book has that id. */
    setStatus(id, status) {
      if (status !== READING && status !== FINISHED) {
        throw new ValidationError(`Unknown status: ${status}`);
      }
      return exclusive(() =>
        update((books) => {
          const book = books.find((candidate) => candidate.id === id);
          if (!book) return null;
          book.status = status;
          book.finishedAt = status === FINISHED ? new Date().toISOString() : null;
          return book;
        }),
      );
    },

    /** @returns the updated book, or null if no book has that id. */
    setNotes(id, notes) {
      const text = clean(notes, LIMITS.notes);
      return exclusive(() =>
        update((books) => {
          const book = books.find((candidate) => candidate.id === id);
          if (!book) return null;
          book.notes = text;
          return book;
        }),
      );
    },
  };
}

export class ValidationError extends Error {}

function clean(value, maxLength) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/\r\n/g, '\n').trim().slice(0, maxLength);
}

