import { FINISHED, READING } from './store.js';

export function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const STYLES = `
  :root {
    --bg: #fbfaf7;
    --card: #ffffff;
    --text: #23201c;
    --muted: #6f6a62;
    --line: #e4e0d8;
    --accent: #7a5b3a;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #1a1917;
      --card: #232120;
      --text: #ece8e2;
      --muted: #a09a91;
      --line: #363330;
      --accent: #cfa878;
    }
  }
  * { box-sizing: border-box; }
  body {
    margin: 0 auto;
    padding: 2.5rem 1.25rem 4rem;
    max-width: 44rem;
    background: var(--bg);
    color: var(--text);
    font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  h1 { font-size: 1.6rem; margin: 0 0 1.75rem; letter-spacing: -0.01em; }
  h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.09em;
       color: var(--muted); margin: 2.5rem 0 0.75rem; }
  a { color: var(--accent); }
  .back { display: inline-block; margin-bottom: 1.5rem; font-size: 0.9rem; text-decoration: none; }
  .back:hover { text-decoration: underline; }
  ul.books { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.6rem; }
  li.book {
    display: flex; align-items: baseline; gap: 1rem;
    background: var(--card); border: 1px solid var(--line); border-radius: 10px;
    padding: 0.85rem 1rem;
  }
  li.book .who { flex: 1 1 auto; min-width: 0; }
  li.book .title { font-weight: 600; text-decoration: none; color: var(--text); }
  li.book .title:hover { text-decoration: underline; text-decoration-color: var(--accent); }
  li.book .author { display: block; color: var(--muted); font-size: 0.88rem; }
  li.book.done .title { color: var(--muted); }
  .empty { color: var(--muted); font-style: italic; margin: 0.25rem 0 0; }
  form.inline { margin: 0; flex: 0 0 auto; }
  button {
    font: inherit; font-size: 0.85rem; cursor: pointer;
    padding: 0.4rem 0.8rem; border-radius: 7px;
    border: 1px solid var(--line); background: var(--bg); color: var(--text);
  }
  button:hover { border-color: var(--accent); color: var(--accent); }
  button.primary {
    background: var(--accent); border-color: var(--accent); color: var(--bg);
    font-size: 0.95rem; padding: 0.6rem 1.2rem;
  }
  button.primary:hover { filter: brightness(1.08); color: var(--bg); }
  .card {
    background: var(--card); border: 1px solid var(--line);
    border-radius: 10px; padding: 1.25rem;
  }
  label { display: block; font-size: 0.85rem; color: var(--muted); margin-bottom: 0.3rem; }
  .field { margin-bottom: 1rem; }
  input, textarea {
    font: inherit; width: 100%; padding: 0.55rem 0.7rem; color: var(--text);
    background: var(--bg); border: 1px solid var(--line); border-radius: 7px;
  }
  input:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
  textarea { min-height: 8rem; resize: vertical; }
  .error {
    background: #fdecea; border: 1px solid #f0b3ad; color: #8c1d13;
    padding: 0.7rem 0.9rem; border-radius: 8px; margin-bottom: 1.25rem; font-size: 0.9rem;
  }
  .detail h1 { margin-bottom: 0.35rem; }
  .detail .byline { color: var(--muted); margin: 0 0 1rem; }
  .badge {
    display: inline-block; font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase;
    border: 1px solid var(--line); border-radius: 999px; padding: 0.2rem 0.65rem; color: var(--muted);
  }
  .meta { color: var(--muted); font-size: 0.85rem; margin: 1rem 0 1.75rem; }
  .actions { display: flex; gap: 0.6rem; align-items: center; margin-top: 0.5rem; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${STYLES}</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function bookRow(book) {
  const finish =
    book.status === READING
      ? `<form class="inline" method="post" action="/books/${escapeHtml(book.id)}/status">
      <input type="hidden" name="status" value="${FINISHED}">
      <input type="hidden" name="redirect" value="/">
      <button type="submit">Mark finished</button>
    </form>`
      : '';

  return `  <li class="book${book.status === FINISHED ? ' done' : ''}">
    <span class="who">
      <a class="title" href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
      <span class="author">${escapeHtml(book.author || 'Unknown author')}</span>
    </span>
    ${finish}
  </li>`;
}

function bookList(books, emptyMessage) {
  if (books.length === 0) return `<p class="empty">${escapeHtml(emptyMessage)}</p>`;
  return `<ul class="books">\n${books.map(bookRow).join('\n')}\n</ul>`;
}

export function renderIndex({ books, error = null, form = {} }) {
  const reading = books.filter((book) => book.status === READING);
  const finished = books.filter((book) => book.status === FINISHED);

  return layout(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
<form class="card" method="post" action="/books">
  <div class="field">
    <label for="title">Title</label>
    <input id="title" name="title" required value="${escapeHtml(form.title ?? '')}">
  </div>
  <div class="field">
    <label for="author">Author</label>
    <input id="author" name="author" value="${escapeHtml(form.author ?? '')}">
  </div>
  <div class="field">
    <label for="notes">Notes (optional)</label>
    <textarea id="notes" name="notes">${escapeHtml(form.notes ?? '')}</textarea>
  </div>
  <button class="primary" type="submit">Add book</button>
</form>`,
  );
}

export function renderBook({ book }) {
  const finished = book.status === FINISHED;
  const id = escapeHtml(book.id);

  const statusForm = `<form class="inline" method="post" action="/books/${id}/status">
    <input type="hidden" name="status" value="${finished ? READING : FINISHED}">
    <input type="hidden" name="redirect" value="/books/${id}">
    <button type="submit">${finished ? 'Move back to reading' : 'Mark finished'}</button>
  </form>`;

  const dates = [`Added ${escapeHtml(formatDate(book.addedAt))}`];
  if (finished && book.finishedAt) {
    dates.push(`finished ${escapeHtml(formatDate(book.finishedAt))}`);
  }

  return layout(
    book.title,
    `<a class="back" href="/">&larr; All books</a>
<div class="detail">
  <h1>${escapeHtml(book.title)}</h1>
  <p class="byline">${escapeHtml(book.author || 'Unknown author')}</p>
  <span class="badge">${finished ? 'Finished' : 'Reading'}</span>
  <p class="meta">${dates.join(' &middot; ')}</p>

  <h2>My notes</h2>
  <form class="card" method="post" action="/books/${id}/notes">
    <div class="field">
      <label for="notes">Anything you want to remember about this book</label>
      <textarea id="notes" name="notes">${escapeHtml(book.notes)}</textarea>
    </div>
    <div class="actions">
      <button class="primary" type="submit">Save notes</button>
      ${statusForm}
    </div>
  </form>
</div>`,
  );
}

export function renderNotFound() {
  return layout(
    'Not found',
    `<h1>Not found</h1>
<p class="empty">That book isn't in the library.</p>
<a class="back" href="/">&larr; All books</a>`,
  );
}

function formatDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown date';
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

