import { FINISHED, READING, ValidationError } from './store.js';
import { renderBook, renderIndex, renderNotFound } from './views.js';

const MAX_BODY_BYTES = 1_000_000;

/**
 * Builds the HTTP request handler. Kept separate from server.js so tests can
 * drive it without binding a port for real.
 */
export function createApp(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      console.error(err);
      if (!res.headersSent) send(res, 500, 'text/plain; charset=utf-8', 'Something went wrong.\n');
    }
  };
}

async function route(store, req, res) {
  const url = new URL(req.url, 'http://localhost');
  const pathname = url.pathname.replace(/\/+$/, '') || '/';
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const books = await store.all();
    return html(res, 200, renderIndex({ books }));
  }

  if (pathname === '/favicon.ico') {
    res.writeHead(204).end();
    return;
  }

  if (pathname === '/books' && method === 'POST') {
    const form = await readForm(req);
    try {
      const book = await store.add({
        title: form.get('title'),
        author: form.get('author'),
        notes: form.get('notes'),
      });
      return redirect(res, `/books/${encodeURIComponent(book.id)}`);
    } catch (err) {
      if (!(err instanceof ValidationError)) throw err;
      const books = await store.all();
      return html(
        res,
        400,
        renderIndex({
          books,
          error: err.message,
          form: {
            title: form.get('title') ?? '',
            author: form.get('author') ?? '',
            notes: form.get('notes') ?? '',
          },
        }),
      );
    }
  }

  const bookMatch = pathname.match(/^\/books\/([^/]+)(\/status|\/notes)?$/);
  if (bookMatch) {
    const id = decodeURIComponent(bookMatch[1]);
    const action = bookMatch[2];

    if (!action) {
      if (method !== 'GET') return methodNotAllowed(res, 'GET');
      const book = await store.get(id);
      if (!book) return html(res, 404, renderNotFound());
      return html(res, 200, renderBook({ book }));
    }

    if (method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    const fallback = `/books/${encodeURIComponent(id)}`;

    if (action === '/status') {
      const status = form.get('status') === READING ? READING : FINISHED;
      const book = await store.setStatus(id, status);
      if (!book) return html(res, 404, renderNotFound());
      return redirect(res, localPath(form.get('redirect'), fallback));
    }

    const book = await store.setNotes(id, form.get('notes'));
    if (!book) return html(res, 404, renderNotFound());
    return redirect(res, fallback);
  }

  return html(res, 404, renderNotFound());
}

async function readForm(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new ValidationError('That submission is too large.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

/** Only ever redirect within this app, never to a URL someone put in a form. */
function localPath(candidate, fallback) {
  if (typeof candidate !== 'string') return fallback;
  if (!candidate.startsWith('/') || candidate.startsWith('//')) return fallback;
  return candidate;
}

function html(res, status, body) {
  send(res, status, 'text/html; charset=utf-8', body);
}

function send(res, status, contentType, body) {
  const buffer = Buffer.from(body, 'utf8');
  res.writeHead(status, {
    'content-type': contentType,
    'content-length': buffer.byteLength,
    'cache-control': 'no-store',
  });
  res.end(res.req?.method === 'HEAD' ? undefined : buffer);
}

function redirect(res, location) {
  // 303 so the browser follows up with a GET and a refresh never re-submits.
  res.writeHead(303, { location, 'cache-control': 'no-store' }).end();
}

function methodNotAllowed(res, allow) {
  res.writeHead(405, { allow, 'content-type': 'text/plain; charset=utf-8' });
  res.end(`Method not allowed. Try ${allow}.\n`);
}

export { FINISHED, READING };

