import { mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { beforeEach, describe, expect, it } from 'vitest';
import { FINISHED, READING, ValidationError, createStore } from '../src/store.js';

let store;

beforeEach(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'books-store-'));
  store = createStore(path.join(dir, 'nested', 'books.json'));
});

describe('createStore', () => {
  it('starts empty when the file does not exist yet', async () => {
    expect(await store.all()).toEqual([]);
  });

  it('adds a book as currently reading', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });

    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', status: READING });
    expect(book.finishedAt).toBeNull();
    expect(await store.get(book.id)).toMatchObject({ title: 'Dune' });
  });

  it('persists books to the JSON file so they survive a restart', async () => {
    await store.add({ title: 'Piranesi', author: 'Susanna Clarke', notes: 'Statues.' });

    const reopened = createStore(store.file);
    expect(await reopened.all()).toMatchObject([{ title: 'Piranesi', notes: 'Statues.' }]);

    const onDisk = JSON.parse(await readFile(store.file, 'utf8'));
    expect(onDisk).toHaveLength(1);
  });

  it('lists the newest addition first', async () => {
    await store.add({ title: 'First' });
    await store.add({ title: 'Second' });

    expect((await store.all()).map((book) => book.title)).toEqual(['Second', 'First']);
  });

  it('trims whitespace and defaults the optional fields', async () => {
    const book = await store.add({ title: '  Solaris  ' });

    expect(book.title).toBe('Solaris');
    expect(book.author).toBe('');
    expect(book.notes).toBe('');
  });

  it('rejects a book with no usable title', async () => {
    await expect(store.add({ title: '   ' })).rejects.toThrow(ValidationError);
    await expect(store.add({})).rejects.toThrow(ValidationError);
    expect(await store.all()).toEqual([]);
  });

  it('marks a book finished and records when', async () => {
    const added = await store.add({ title: 'Ulysses' });

    const finished = await store.setStatus(added.id, FINISHED);

    expect(finished.status).toBe(FINISHED);
    expect(Number.isNaN(Date.parse(finished.finishedAt))).toBe(false);
  });

  it('clears the finish date when a book goes back to reading', async () => {
    const added = await store.add({ title: 'Ulysses' });
    await store.setStatus(added.id, FINISHED);

    const reading = await store.setStatus(added.id, READING);

    expect(reading.status).toBe(READING);
    expect(reading.finishedAt).toBeNull();
  });

  it('rejects an unknown status', async () => {
    const added = await store.add({ title: 'Ulysses' });
    await expect(store.setStatus(added.id, 'abandoned')).rejects.toThrow(ValidationError);
  });

  it('saves notes', async () => {
    const added = await store.add({ title: 'Beloved' });

    const updated = await store.setNotes(added.id, '  Chapter 3 is the hinge.  ');

    expect(updated.notes).toBe('Chapter 3 is the hinge.');
    expect((await store.get(added.id)).notes).toBe('Chapter 3 is the hinge.');
  });

  it('reports a missing book instead of throwing', async () => {
    expect(await store.get('nope')).toBeNull();
    expect(await store.setStatus('nope', FINISHED)).toBeNull();
    expect(await store.setNotes('nope', 'hi')).toBeNull();
  });

  it('keeps every book when writes overlap', async () => {
    const titles = Array.from({ length: 12 }, (_, i) => `Book ${i}`);

    await Promise.all(titles.map((title) => store.add({ title })));

    const stored = (await store.all()).map((book) => book.title).sort();
    expect(stored).toEqual(titles.slice().sort());
  });

  it('refuses to work with a file that is not a JSON array', async () => {
    await store.add({ title: 'Seed' });
    await writeFile(store.file, '{"not":"an array"}', 'utf8');

    await expect(store.all()).rejects.toThrow(/JSON array/);
  });
});

