import http from 'node:http';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { FINISHED, READING, createStore } from '../src/store.js';

let server;
let base;
let store;

beforeEach(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'books-app-'));
  store = createStore(path.join(dir, 'books.json'));
  server = http.createServer(createApp(store));
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((resolve) => server.close(resolve));
});

function post(pathname, fields) {
  return fetch(`${base}${pathname}`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

const get = (pathname) => fetch(`${base}${pathname}`);

describe('the reading list page', () => {
  it('shows both shelves', async () => {
    const res = await get('/');
    const body = await res.text();

    expect(res.status).toBe(200);
    expect(body).toContain('Currently reading');
    expect(body).toContain('Finished');
    expect(body).toContain('Nothing on the go right now.');
  });

  it('lists a book under the shelf matching its status', async () => {
    await store.add({ title: 'Reading now' });
    const done = await store.add({ title: 'All done' });
    await store.setStatus(done.id, FINISHED);

    const body = await get('/').then((res) => res.text());
    const reading = body.indexOf('Currently reading');
    const finished = body.indexOf('>Finished<');

    expect(body.indexOf('Reading now')).toBeGreaterThan(reading);
    expect(body.indexOf('Reading now')).toBeLessThan(finished);
    expect(body.indexOf('All done')).toBeGreaterThan(finished);
  });

  it('links each book to its own page', async () => {
    const book = await store.add({ title: 'Dune' });

    const body = await get('/').then((res) => res.text());
    expect(body).toContain(`href="/books/${book.id}"`);
  });
});

describe('adding a book', () => {
  it('saves the book and redirects back to the list', async () => {
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Sand.' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect(await store.all()).toMatchObject([
      { title: 'Dune', author: 'Frank Herbert', notes: 'Sand.', status: READING },
    ]);
  });

  it('re-shows the form with an error and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: 'Someone', notes: 'Kept' });
    const body = await res.text();

    expect(res.status).toBe(400);
    expect(body).toContain('A title is required.');
    expect(body).toContain('value="Someone"');
    expect(body).toContain('Kept');
    expect(await store.all()).toEqual([]);
  });
});

describe('a single book page', () => {
  it('shows the title, author and notes', async () => {
    const book = await store.add({
      title: 'Piranesi',
      author: 'Susanna Clarke',
      notes: 'The House is the world.',
    });

    const res = await get(`/books/${book.id}`);
    const body = await res.text();

    expect(res.status).toBe(200);
    expect(body).toContain('Piranesi');
    expect(body).toContain('Susanna Clarke');
    expect(body).toContain('The House is the world.');
  });

  it('is reachable by URL alone, so the link can be shared', async () => {
    const book = await store.add({ title: 'Shared Book' });

    // A fresh client with no cookies or session, exactly like a friend clicking a link.
    const res = await fetch(`${base}/books/${book.id}`, { headers: { cookie: '' } });

    expect(res.status).toBe(200);
    expect(await res.text()).toContain('Shared Book');
  });

  it('says so when the book does not exist', async () => {
    const res = await get('/books/does-not-exist');

    expect(res.status).toBe(404);
    expect(await res.text()).toContain("isn't in the library");
  });

  it('saves edited notes', async () => {
    const book = await store.add({ title: 'Beloved' });

    const res = await post(`/books/${book.id}/notes`, { notes: 'Read again in winter.' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
    expect((await store.get(book.id)).notes).toBe('Read again in winter.');
  });
});

describe('marking a book finished', () => {
  it('moves it to the finished shelf and returns to the list', async () => {
    const book = await store.add({ title: 'Dune' });

    const res = await post(`/books/${book.id}/status`, { status: FINISHED, redirect: '/' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect((await store.get(book.id)).status).toBe(FINISHED);
  });

  it('can be undone from the book page', async () => {
    const book = await store.add({ title: 'Dune' });
    await store.setStatus(book.id, FINISHED);

    await post(`/books/${book.id}/status`, { status: READING, redirect: `/books/${book.id}` });

    expect((await store.get(book.id)).status).toBe(READING);
  });

  it('404s for an unknown book', async () => {
    const res = await post('/books/nope/status', { status: FINISHED });
    expect(res.status).toBe(404);
  });

  it('ignores an off-site redirect target', async () => {
    const book = await store.add({ title: 'Dune' });

    const res = await post(`/books/${book.id}/status`, {
      status: FINISHED,
      redirect: 'https://evil.example.com/',
    });

    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
  });
});

describe('general request handling', () => {
  it('escapes HTML in whatever the user typed', async () => {
    const book = await store.add({
      title: '<script>alert(1)</script>',
      author: '"quoted"',
      notes: 'a & b',
    });

    const body = await get(`/books/${book.id}`).then((res) => res.text());

    expect(body).not.toContain('<script>alert(1)</script>');
    expect(body).toContain('&lt;script&gt;');
    expect(body).toContain('&quot;quoted&quot;');
    expect(body).toContain('a &amp; b');
  });

  it('404s an unknown path', async () => {
    expect((await get('/nope')).status).toBe(404);
  });

  it('rejects the wrong method with 405', async () => {
    const res = await post('/', {});

    expect(res.status).toBe(405);
    expect(res.headers.get('allow')).toBe('GET');
  });
});

